def max_value_on_paths(N, grid_values):
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        grid[x - 1][y - 1] = value

    max_sum = 0
    for i in range(N):
        for j in range(N):
            if grid[i][j] != 0:
                max_sum = max(max_sum, grid[i][j] + grid[N - 1 - i][N - 1 - j])

    return max_sum
