def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a matrix to store the number of chatting pairs that can be separated by adding an aisle in each position
    matrix = [[0] * (N + 1) for _ in range(M + 1)]

    # Loop through each chatting pair and increment the value in the matrix for each position where the pair can be separated by an aisle
    for pair in chatting_pairs:
        row1, col1, row2, col2 = pair
        for i in range(row1, row2 + 1):
            for j in range(col1, col2 + 1):
                matrix[i][j] += 1

    # Initialize a set to store the optimal row and column indices for the aisles
    aisle_indices = set()

    # Loop through each position in the matrix and check if it can be separated by an aisle
    for i in range(1, M + 1):
        for j in range(1, N + 1):
            if matrix[i][j] > 0:
                # If the position can be separated by an aisle, add its row and column indices to the set
                aisle_indices.add((i, j))

    # Convert the set to a list and sort it by row index, then by column index
    aisle_indices = sorted(list(aisle_indices), key=lambda x: (x[0], x[1]))

    # Return the list of optimal row and column indices for the aisles
    return list(map(str, [i[0] for i in aisle_indices])) + [" ".join(map(str, [i[1] for i in aisle_indices]))]
