def decode(encoded, original, message):
    # Create a dictionary to map encoded letters to their original letters
    encoding_dict = {}
    for i in range(len(encoded)):
        encoding_dict[encoded[i]] = original[i]

    # Check if the encoding dictionary is a valid mapping
    # If the dictionary contains a letter that is not in the original string, return "Failed"
    for key in encoding_dict:
        if key not in original:
            return "Failed"

    # Check if the encoding dictionary is one-to-one
    # If the dictionary maps the same encoded letter to different original letters, return "Failed"
    for key, value in encoding_dict.items():
        if value in encoding_dict.values():
            return "Failed"

    # Use the encoding dictionary to decode the message
    decoded_message = ""
    for char in message:
        decoded_message += encoding_dict[char]

    return decoded_message
