def count_partitions(n, k, x):
    if k == 1:
        return 1
    if k == 2:
        return n - x + 1
    if k == 3:
        return (n - 2*x + 1) * (n - x) // 2
    if k == 4:
        return (n - 3*x + 1) * (n - 2*x) * (n - x) // 6
    return count_partitions(n, k-1, x) + count_partitions(n-k+1, k-1, x)
