def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 1:
        return 0
    elif n == 2:
        return 1 if heights[0] > heights[1] else 0
    else:
        left = 0
        right = n - 1
        count = 0
        while left < right:
            if heights[left] > heights[left + 1]:
                left += 1
                count += 1
            elif heights[right] < heights[right - 1]:
                right -= 1
                count += 1
            else:
                left += 1
                right -= 1
        return count + minimum_students_to_leave(heights[:left] + heights[left + 1:]) + minimum_students_to_leave(heights[left + 1:] + heights[:right])
